// [S4] Embed the locked brand font "Ink Free" so renders are on-brand on ANY host.
// The per-video render scripts override Remotion's publicDir to the video's assets
// dir, so a served public/fonts/*.ttf would 404 in production; a base64 data URI is
// publicDir-independent and fully self-contained. loadEngineFont() blocks the frame
// (delayRender) until the face is ready and asserts the requested family resolved.
import {continueRender, delayRender} from 'remotion';

export const ENGINE_FONT_FAMILY = 'Ink Free';

const INKFREE_TTF_BASE64 =
  '';

let started = false;
export const loadEngineFont = (): void => {
  if (started || typeof document === 'undefined' || typeof FontFace === 'undefined') return;
  started = true;
  const handle = delayRender(`load font "${ENGINE_FONT_FAMILY}"`);
  const face = new FontFace(
    ENGINE_FONT_FAMILY,
    `url(data:font/ttf;base64,${INKFREE_TTF_BASE64}) format('truetype')`,
  );
  face
    .load()
    .then((loaded) => {
      document.fonts.add(loaded);
      // [S4] fail-loud: the resolved family must be the one we asked for.
      if (!document.fonts.check(`32px "${ENGINE_FONT_FAMILY}"`)) {
        throw new Error(`[engine] font "${ENGINE_FONT_FAMILY}" did not resolve after load`);
      }
      continueRender(handle);
    })
    .catch((err) => {
      throw new Error(`[engine] failed to load locked font "${ENGINE_FONT_FAMILY}": ${err}`);
    });
};
